// Package ui embeds the compiled frontend SPA so it can be served by the
// controller binary without any external files.
//
// The dist/ directory is NOT checked into source control — it is generated by
// the build script (scripts/build.sh) which runs `npm run build` and then
// copies frontend/dist into this directory before `go build`.
package ui

import (
	"embed"
	"io/fs"
	"log"
)

// Files holds the compiled Vue SPA (HTML, CSS, JS, assets).
// The path "dist" refers to the dist/ subdirectory of this package.
//
//go:embed dist
var Files embed.FS

// FS returns a sub-filesystem rooted at "dist", suitable for http.FileServer.
func FS() fs.FS {
	sub, err := fs.Sub(Files, "dist")
	if err != nil {
		log.Fatalf("ui: failed to sub dist: %v", err)
	}
	return sub
}
